  aiFeedback: defineTable({
    userId: v.string(),
    traceId: v.string(),
    spanId: v.optional(v.string()),
    feature: v.string(),
    sentiment: v.union(v.literal("positive"), v.literal("negative")),
    reason: v.optional(
      v.union(
        v.literal("grounding"),
        v.literal("usefulness"),
        v.literal("tone"),
        v.litera…336 tokens truncated…   result: v.any(),
